      evalcoordsobj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
  PyArrayObject *ncavg = (PyArrayObject *)PyArray_FROM_OTF(
      ncavgobj, NPY_INT32, NPY_ARRAY_IN_ARRAY);
